  return '\\uFEFF' + [['Имя', 'Email', 'Компания', 'Статус', 'Тариф', 'Дата регистрации', 'Выручка'], ...clients.map(c => [c.name, c.email, c.company, statusLabels[c.status], c.plan, c.date, c.revenue])].map(row => row.map(escape).join(';')).join('\\r\\n');
}
