    {id: '"'plan', name: 'Тариф', meta: {sort: true}, width: '11%', template: c => <span className={"'`plan plan-${c.plan === '"'Бизнес' ? 'business' : c.plan === 'Про' ? 'pro' : 'basic'}"'`}>{c.plan}</span>},
