.selection-bar {display: flex; gap: var(--g-spacing-3); align-items: center; padding: var(--g-spacing-3) var(--g-spacing-5); background: var(--g-color-base-selection); color: var(--app-accent); font-size: 12px; border-top: 1px solid var(--g-color-line-generic);}
