.table-footer {display: flex; justify-content: space-between; align-items: center; padding: var(--g-spacing-4) var(--g-spacing-5); border-top: 1px solid var(--g-color-line-generic); gap: var(--g-spacing-4);}
.page-size {display: flex; align-items: center; gap: var(--g-spacing-3); color: var(--g-color-text-secondary); font-size: 11px;}
.rows-summary {margin-left: var(--g-spacing-3);}
.workspace-footer {display: flex; justify-content: space-between; gap: var(--g-spacing-4); margin-top: var(--g-spacing-5); font-size: 10px; color: var(--g-color-text-hint);}
.workspace-footer > span:first-child {display: flex; align-items: center; gap: var(--g-spacing-2);}
.empty-actions {padding: var(--g-spacing-5); text-align: center;}
.notice {position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: var(--g-spacing-3); background: var(--g-color-base-background); padding: var(--g-spacing-3) var(--g-spacing-4); border: 1px solid var(--g-color-line-positive); border-radius: var(--g-border-radius-l); box-shadow: 0 4px 24px var(--g-color-sfx-shadow); z-index: 10; max-width: calc(100vw - 32px);}
.notice > svg {color: var(--app-accent); flex-shrink: 0;}
.dialog {width: min(460px, calc(100vw - 32px)); padding: var(--g-spacing-7);}
.dialog-header {display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-4);}
.form-field {display: flex; flex-direction: column; gap: var(--g-spacing-2); margin-top: var(--g-spacing-4); font-size: 13px;}
.dialog-actions {display: flex; justify-content: flex-end; gap: var(--g-spacing-3); margin-top: var(--g-spacing-6);}
.form-error {color: var(--g-color-text-danger);}
.help-content {line-height: 1.6; margin-bottom: var(--g-spacing-5);}
.detail-identity {display: flex; align-items: center; gap: var(--g-spacing-3); margin: var(--g-spacing-5) 0;}
.detail-list {display: grid; grid-template-columns: 1fr 1.3fr; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-6);}
.detail-list dt {color: var(--g-color-text-secondary);}
.detail-list dd {margin: 0; overflow-wrap: anywhere;}
a {color: var(--g-color-text-link);}
@media (min-width: 1500px) {.workspace {padding-top: var(--g-spacing-10);}}
@media (max-width: 1000px) {
  .workspace {padding: var(--g-spacing-6);}
  .workspace-label {display: none;}
  .stats-grid {grid-template-columns: repeat(2, 1fr);}
  .table-live {display: none;}
  .stat-bottom {justify-content: space-between;}
  .workspace-footer > span:last-child {display: none;}
}
@media (max-width: 600px) {
  .page-header {height: 60px;}
  .header-inner {padding: 0 var(--g-spacing-4); gap: var(--g-spacing-4);}
  .breadcrumb {font-size: 12px;}
  .breadcrumb > span:first-child, .breadcrumb > svg {display: none;}
  .header-right {gap: var(--g-spacing-2);}
  .header-right .header-divider {display: none;}
  .workspace {padding: var(--g-spacing-5) var(--g-spacing-3);}
  .page-title-row {align-items: flex-start; flex-direction: column; gap: var(--g-spacing-5); margin-bottom: var(--g-spacing-5);}
  .page-actions {width: 100%;}
  .page-actions > :last-child {flex: 1;}
  .page-description {font-size: 12px;}
  .stats-grid {gap: var(--g-spacing-2); margin-bottom: var(--g-spacing-5);}
  .stat-card {padding: var(--g-spacing-3);}
  .stat-top {font-size: 11px; gap: var(--g-spacing-1);}
  .stat-top svg {width: 15px;}
  .stat-bottom {align-items: flex-start; flex-direction: column; gap: var(--g-spacing-1); margin-top: var(--g-spacing-2);}
  .stat-bottom > .g-text {font-size: 23px; line-height: 30px; letter-spacing: -1px;}
  .revenue-icon {display: none;}
  .stat-caption {font-size: 9px;}
  .table-tabs {padding: 0 var(--g-spacing-3); gap: var(--g-spacing-3); overflow-x: auto; min-height: 50px;}
  .table-tab.g-button {height: 50px; font-size: 12px;}
  .tab-count {display: none;}
  .table-toolbar {flex-direction: column; align-items: stretch; padding: var(--g-spacing-3); gap: var(--g-spacing-3);}
  .search-input {width: 100%;}
  .filter-controls {justify-content: space-between;}
  .filter-controls .g-select {flex: 1; min-width: 0;}
  .table-footer {flex-direction: column; padding: var(--g-spacing-4) var(--g-spacing-3);}
  .page-size {width: 100%;}
  .rows-summary {margin-left: auto;}
  .selection-bar {flex-wrap: wrap; gap: var(--g-spacing-2); padding: var(--g-spacing-3);}
  .selection-bar > span {width: 100%;}
  .workspace-footer {line-height: 1.5; font-size: 10px;}
}
